/**
 * A Logger class for T3D
 *
 * This satic class defines severity levels of messages and provides
 * basic logging functionality. Replacing the reference to
 *
 * @namespace
 * @static
 */
class Logger {
    TYPE_ERROR = 4;
    TYPE_WARNING = 3;
    TYPE_MESSAGE = 2;
    TYPE_PROGRESS = 1;
    TYPE_DEBUG = 0;
    logFunctions = new Array(5);
    constructor() {
        this.logFunctions[this.TYPE_ERROR] = function (...args) {
            console.error(...args);
        };
        this.logFunctions[this.TYPE_WARNING] = function (...args) {
            console.warn(...args);
        };
        this.logFunctions[this.TYPE_MESSAGE] = function (...args) {
            console.log(...args);
        };
        this.logFunctions[this.TYPE_PROGRESS] = function (...args) {
            const argArr = args;
            argArr.unshift("Progress: ");
            console.log(...argArr);
        };
        this.logFunctions[this.TYPE_DEBUG] = function (...args) {
            const argArr = args;
            console.debug(...argArr);
        };
    }
    /**
     * Main logging method. Takes 1 to N arguments. If there are more than 1 arguments
     * the first argument is interpreted as severity. If there is only one argument
     * severity defaults to
     * {{#crossLink "Logger/TYPE_MESSAGE:property"}}{{/crossLink}}.
     *
     * The following arguments are passed to a logging function matching the
     * severity.
     *
  
    *
    */
    log(...args) {
        /// Require at least 1 argument
        if (arguments.length === 0) {
            return;
        }
        /// Parse arguments to an actual array
        const argArr = args;
        /// Default to message if just one argument was passed
        if (argArr.length === 1) {
            argArr.unshift(this.TYPE_MESSAGE);
        }
        /// Otherwise 1st arg is severity, log/warn/error
        const severity = Math.max(0, Math.min(this.logFunctions.length, argArr.shift()));
        const logFunc = this.logFunctions[severity];
        /// Ouput the rest of the arguments
        logFunc.apply(this, argArr);
    }
}
const logger = new Logger();

/// Indexed DB versioning
const DB_VERSION = 4;
/**
 * This class handles offline storage of the .dat indexes and files metadata
 * @class PersistantStore
 */
class PersistantStore {
    _dbConnection;
    constructor() {
        // They may be multiple connection request issued at the same time, but it's actually okay since
        // as soon as they are registered, the not-used ones will get garbage collected
        this._dbConnection = undefined;
        this._getConnection();
    }
    /**
     *   Initialize the IndexedDB connection and manages version changes.
     *
     * @async
     * @private
     * @returns {Promise<IDBDatabase>} Promise to the Database connection
     */
    _getConnection() {
        const self = this;
        return new Promise((resolve, reject) => {
            if (self._dbConnection)
                resolve(self._dbConnection);
            // Let us open our database
            const request = window.indexedDB.open("Tyria3DLibrary", DB_VERSION);
            /// onblocked is fired when the db needs an upgrade but an older version is opened in another tab
            request.onblocked = () => {
                logger.log(logger.TYPE_ERROR, "The T3D persistant database cannot be upgraded while the app is opened somewhere else.");
            };
            /// fired when the database needs to be upgraded (or the first time)
            request.onupgradeneeded = (event) => {
                // Probably bugged
                //@ts-ignore
                const db = event.target.result;
                const currentVersion = event.oldVersion;
                if (currentVersion < 2) {
                    db.createObjectStore("listings", {
                        autoIncrement: true,
                    });
                }
                if (currentVersion < 3) {
                    const storeListing = event.currentTarget.transaction.objectStore("listings");
                    storeListing.createIndex("filename", "filename", { unique: false });
                }
            };
            request.onsuccess = (event) => {
                self._dbConnection = event.target.result;
                //@ts-ignore
                self.isReady = true;
                resolve(self._dbConnection);
            };
            request.onerror = () => {
                logger.log(logger.TYPE_ERROR, "The T3D persistant database could not be opened.");
                reject();
            };
        });
    }
    /**
     *   Add or update a listing into the database
     *
     * @async
     * @param {number|undefined} id This ID doesn't really matter, it's just the index of the object in the database, can be undefined
     * @param {Array} listing
     * @param {string} fileName .dat file name, allows to have multiple listings for different .dat files.
     * @param {boolean} isComplete Keep back the information if that was the last update on the current scan or not.
     * @returns {Promise<number>} On success, the number is the object key in the database
     */
    putListing(id, listing, fileName, isComplete) {
        const self = this;
        return new Promise((resolve, reject) => {
            self._getConnection().then((db) => {
                const store = db.transaction(["listings"], "readwrite").objectStore("listings");
                const request = id
                    ? store.put({ array: listing, filename: fileName, complete: isComplete }, id)
                    : store.put({ array: listing, name: fileName });
                request.onsuccess = () => {
                    resolve(request.result);
                };
                request.onerror = () => {
                    reject();
                };
            });
        });
    }
    /**
     * Returns the last valid listing in the database
     *
     * @async
     * @param {string} fileName .dat file name, allows to have multiple listings for different .dat files.
     * @returns {Promise<{array: Array, key: number, complete: boolean}>}
     *      array: the last listing
     *      key: the index of the last listing in the database
     */
    getLastListing(fileName) {
        const self = this;
        return new Promise((resolve) => {
            self._getConnection().then((db) => {
                const listingsStore = db.transaction(["listings"], "readonly").objectStore("listings").index("filename");
                listingsStore.openCursor(IDBKeyRange.only(fileName), "prev").onsuccess = (event) => {
                    const cursor = event.target.result;
                    if (!cursor)
                        resolve({ array: [], key: undefined, complete: true });
                    else {
                        resolve({
                            array: cursor.value.array,
                            key: cursor.primaryKey,
                            complete: cursor.value.complete,
                        });
                    }
                };
            });
        });
    }
}

/**
 * Organized thread pool of extractors
 */
class DataReader {
    settings;
    _workerPool;
    _workerLoad;
    _inflateCallbacks;
    _scanCallbacks;
    _scanByMft;
    _nextScanId;
    _pendingScanJobs;
    _pendingInflateJobs;
    constructor(settings) {
        this.settings = settings;
        this._workerPool = [];
        this._workerLoad = [];
        this._inflateCallbacks = [];
        this._scanCallbacks = [];
        this._scanByMft = new Map();
        this._nextScanId = 1;
        this._pendingScanJobs = [];
        this._pendingInflateJobs = [];
        for (let i = 0; i < settings.workersNb; i++) {
            this._startWorker(settings.workerPath);
        }
    }
    /**
     * Give every worker its own reference to the archive File so they can
     * do their own slicing during the type-detection scan. Cheap — the
     * underlying blob handle is shared, not copied.
     */
    init(file) {
        for (const worker of this._workerPool) {
            worker.postMessage({ type: "init", file });
        }
    }
    /**
     * Worker-side scan: slice `length` bytes at `offset`, inflate up to
     * `capLength` bytes if `compressed`, return the resulting buffer.
     * Concurrent calls for the same `mftId` are coalesced.
     */
    scan(mftId, offset, length, capLength, compressed) {
        return new Promise((resolve, reject) => {
            const existingId = this._scanByMft.get(mftId);
            if (existingId !== undefined && this._scanCallbacks[existingId]) {
                this._scanCallbacks[existingId].push({ resolve, reject });
                return;
            }
            const id = this._nextScanId++;
            this._scanCallbacks[id] = [{ resolve, reject }];
            this._scanByMft.set(mftId, id);
            this._enqueueScanJob({
                kind: "scan",
                id,
                mftId,
                offset,
                length,
                capLength,
                compressed,
            });
        });
    }
    inflate(buffer, _size, mftId, isImage, capLength) {
        return new Promise((resolve, reject) => {
            const arrayBuffer = buffer;
            // If no capLength then inflate the whole file
            if (!capLength || capLength < 0) {
                capLength = 0;
            }
            // Buffer length size check
            if (arrayBuffer.byteLength < 12) {
                logger.log(logger.TYPE_WARNING, `not inflating, length is too short (${arrayBuffer.byteLength})`, mftId);
                reject(new Error("Couldn't inflate " + mftId + " (mftId)"));
                return;
            }
            // Register the callback
            if (this._inflateCallbacks[mftId]) {
                this._inflateCallbacks[mftId].push({
                    resolve: resolve,
                    reject: reject,
                });
                /// No need to make another call, just wait for callback event to fire.
                return;
            }
            else {
                this._inflateCallbacks[mftId] = [{ resolve: resolve, reject: reject }];
            }
            this._enqueueInflateJob({
                kind: "inflate",
                mftId,
                buffer: arrayBuffer,
                isImage: isImage === true,
                capLength,
            });
        });
    }
    // Initialization function for creating a new worker (thread)
    _startWorker(path) {
        const self = this;
        const worker = new Worker(path);
        const selfWorkerId = this._workerPool.push(worker) - 1;
        if (this._workerLoad.push(0) !== selfWorkerId + 1) {
            throw new Error("WorkerLoad and WorkerPool don't have the same length");
        }
        worker.onmessage = function (message_event) {
            self._workerLoad[selfWorkerId] = 0;
            const data = message_event.data;
            // Scan protocol — object messages with a `type` field.
            if (data && !Array.isArray(data) && typeof data === "object" && data.type) {
                self._handleScanResponse(data);
                self._drainQueues(selfWorkerId);
                return;
            }
            let mftId;
            // Legacy inflate error path — string message.
            if (typeof data === "string") {
                logger.log(logger.TYPE_WARNING, "Inflater threw an error", data);
                mftId = parseInt(data.split(":")[0]);
                const callbacks = self._inflateCallbacks[mftId];
                delete self._inflateCallbacks[mftId];
                if (callbacks) {
                    for (const callback of callbacks) {
                        callback.reject(new Error(data));
                    }
                }
            }
            else {
                mftId = data[0];
                const callbacks = self._inflateCallbacks[mftId];
                delete self._inflateCallbacks[mftId];
                if (callbacks) {
                    for (const callback of callbacks) {
                        callback.resolve({
                            buffer: data[1],
                            dxtType: data[2],
                            imageWidth: data[3],
                            imageHeight: data[4],
                        });
                    }
                }
                else {
                    logger.log(logger.TYPE_ERROR, "Inflater threw an error", data);
                }
            }
            self._drainQueues(selfWorkerId);
        };
    }
    _handleScanResponse(data) {
        const callbacks = this._scanCallbacks[data.id];
        this._scanCallbacks[data.id] = undefined;
        // Drop the mftId→id mapping. We don't know which mftId this was for from
        // the response, but the dedup map's lifecycle matches the callbacks: when
        // callbacks resolve, no future scan() can coalesce onto this id anyway.
        // Walk the small map to find and remove; map stays bounded by concurrent
        // unique mftIds in flight, never the full archive.
        for (const [mft, sid] of this._scanByMft) {
            if (sid === data.id) {
                this._scanByMft.delete(mft);
                break;
            }
        }
        if (!callbacks)
            return;
        if (data.type === "scan-result" && data.buffer) {
            for (const cb of callbacks)
                cb.resolve(data.buffer);
        }
        else {
            const err = new Error(data.error || "scan failed");
            for (const cb of callbacks)
                cb.reject(err);
        }
    }
    _enqueueScanJob(job) {
        const workerId = this._findIdleWorkerIndex();
        if (workerId !== -1 && this._pendingInflateJobs.length === 0) {
            this._dispatchScanJob(workerId, job);
            return;
        }
        this._pendingScanJobs.push(job);
    }
    _enqueueInflateJob(job) {
        const workerId = this._findIdleWorkerIndex();
        if (workerId !== -1) {
            this._dispatchInflateJob(workerId, job);
            return;
        }
        this._pendingInflateJobs.push(job);
    }
    _drainQueues(workerId) {
        if (this._workerLoad[workerId] !== 0)
            return;
        const inflateJob = this._pendingInflateJobs.shift();
        if (inflateJob) {
            this._dispatchInflateJob(workerId, inflateJob);
            return;
        }
        const scanJob = this._pendingScanJobs.shift();
        if (scanJob) {
            this._dispatchScanJob(workerId, scanJob);
        }
    }
    _dispatchScanJob(workerId, job) {
        this._workerLoad[workerId] = 1;
        this._workerPool[workerId].postMessage({
            type: "scan",
            id: job.id,
            mftId: job.mftId,
            offset: job.offset,
            length: job.length,
            capLength: job.capLength,
            compressed: job.compressed,
        });
    }
    _dispatchInflateJob(workerId, job) {
        this._workerLoad[workerId] = 1;
        this._workerPool[workerId].postMessage([job.mftId, job.buffer, job.isImage, job.capLength], [job.buffer]);
    }
    _findIdleWorkerIndex() {
        for (let i = 0; i < this._workerLoad.length; i++) {
            if (this._workerLoad[i] === 0)
                return i;
        }
        return -1;
    }
}

